/**
 * seedRoute.ts — the one line a new voice session opens knowing.
 *
 * GET /athletes/:id/voice-seed?conversationId=…, mounted at /api/internal/voice.
 * The caller is TRUSTED INFRASTRUCTURE: no session, no `req.athleteId`, and the
 * shared secret is the entire authorization boundary. See ./auth.
 *
 * ── Why the worker cannot do this itself ─────────────────────────────────────
 * The artifact lives in Postgres and the copy is generated by ./voiceSeed, both
 * of which are here. The worker has no database. So this route does the read, the
 * id→name resolution and the template, and hands back ONE string.
 *
 * ── The names, and why resolving them here is the safe place ─────────────────
 * The artifact stores ids on purpose — names are extracted from brand email and
 * are not ours. Turning them back into speech needs a lookup, and doing it here
 * means the lookup is athlete-scoped SQL rather than something the worker
 * assembles. `buildVoiceSeed` then sanitises every name before it reaches a
 * sentence (single line, bounded, no markup) and drops any that fails, so a
 * brand row carrying an injection payload costs us a mention, not a spoken
 * instruction.
 *
 * ── Silence is a real answer ─────────────────────────────────────────────────
 * `{ seed: null }` whenever there is nothing worth saying: no artifact, an empty
 * one, or one whose entries cannot be safely named. The worker injects nothing at
 * all in that case — it does NOT inject an empty message. An athlete who has only
 * ever texted gets null here, deliberately: this route never reads
 * `chat_messages`, because that history is full of brand and email prose and this
 * output is spoken aloud.
 */

import { Router, type Request, type Response } from "express";
import { and, eq, inArray } from "drizzle-orm";
import { db } from "../db";
import { deals, inboxBrands } from "../../shared/schema";
import { withTimeout } from "../lib/withTimeout";
import { createLogger } from "../logger";
import { voiceAuthorized, sendVoiceRefusal, UUID_RE } from "./auth";
import { getVoiceContext } from "./voiceContext";
import { buildVoiceSeed, type SeedNames } from "./voiceSeed";

const logger = createLogger("voice/seed");

const router = Router();

/**
 * Bounds the whole thing. This runs at session start, BEFORE the athlete can
 * speak, so it is the one place a slow read delays the greeting. A timeout means
 * no seed rather than a late one — memory is worth having, not worth waiting for.
 */
const READ_TIMEOUT_MS = 2_000;

/**
 * Resolves the ids in the artifact to display names, athlete-scoped.
 *
 * Deal names come from `deals.brand_name` (the deal's own record of who it is
 * with) rather than by joining to `inbox_brands`, for the reason ./dealResolver
 * documents at length: the deal→brand link runs through `inbox_threads.brand_id`
 * and is WRONG on live data — the athlete's Prime Hydration deal points at a
 * thread whose brand is Finish Line. Reading the name off the deal itself cannot
 * inherit that mis-link.
 */
async function resolveNames(
  athleteId: string,
  dealIds: string[],
  brandIds: number[],
): Promise<SeedNames> {
  const names: SeedNames = { deals: {}, brands: {} };

  if (dealIds.length) {
    const rows = await db
      .select({ id: deals.id, brand: deals.brand_name })
      .from(deals)
      .where(and(eq(deals.athlete_id, athleteId), inArray(deals.id, dealIds)));
    for (const r of rows) if (r.brand) names.deals[r.id] = r.brand;
  }

  if (brandIds.length) {
    // inbox_brands is global reference data with no athlete_id — see getBrand.ts.
    const rows = await db
      .select({ id: inboxBrands.id, name: inboxBrands.name })
      .from(inboxBrands)
      .where(inArray(inboxBrands.id, brandIds));
    for (const r of rows) if (r.name) names.brands[r.id] = r.name;
  }

  return names;
}

// GET /athletes/:id/voice-seed — context for a session that is about to start.
// Read-only: no writes, no model call, no side effects.
router.get("/athletes/:id/voice-seed", async (req: Request, res: Response) => {
  res.setHeader("Cache-Control", "no-store");

  const voiceAuth = await voiceAuthorized(req, req.params.id);
  if (!voiceAuth.ok) {
    sendVoiceRefusal(res, voiceAuth);
    return;
  }

  const { id } = req.params;
  if (!UUID_RE.test(id)) {
    res.status(400).json({ error: "Invalid athlete id" });
    return;
  }

  const conversationId =
    typeof req.query.conversationId === "string"
      ? req.query.conversationId
      : "";
  if (!UUID_RE.test(conversationId)) {
    res.status(400).json({ error: "Invalid conversation id" });
    return;
  }

  try {
    const state = await withTimeout(
      getVoiceContext(id, conversationId),
      READ_TIMEOUT_MS,
      "voice seed read",
    );

    if (!state) {
      logger.info(
        { athleteId: id, outcome: "none" },
        "Voice seed — nothing yet",
      );
      res.json({ seed: null });
      return;
    }

    const names = await withTimeout(
      resolveNames(
        id,
        state.dealsDiscussed.map((d) => d.dealId),
        [
          ...state.brandsDiscussed.map((b) => b.brandId),
          // A deal's brandId can name it too when the deal row cannot.
          ...state.dealsDiscussed
            .map((d) => d.brandId)
            .filter((b): b is number => b !== null),
        ],
      ),
      READ_TIMEOUT_MS,
      "voice seed names",
    );

    const seed = buildVoiceSeed(state, names);
    logger.info(
      {
        athleteId: id,
        outcome: seed ? "seeded" : "silent",
        chars: seed?.length ?? 0,
      },
      "Voice seed built",
    );
    res.json({ seed });
  } catch (err: any) {
    // Never cost a session its start. No seed is a working session with no
    // memory; a failed request would be a session that never began.
    logger.warn(
      { athleteId: id, error: err.message },
      "Voice seed failed — starting without memory",
    );
    res.json({ seed: null });
  }
});

export default router;
